'use client';

import {
  DndContext,
  DragOverlay,
  MouseSensor,
  TouchSensor,
  pointerWithin,
  useSensor,
  useSensors,
  type DragEndEvent,
  type DragOverEvent,
  type DragStartEvent,
} from '@dnd-kit/core';
import { LayoutGroup, useReducedMotion } from 'motion/react';
import { useId, useState } from 'react';

import { useSession } from '@/registry/ndeko/hooks/use-session';
import { useTimeouts } from '@/registry/ndeko/hooks/use-timeouts';
import {
  CheckIcon,
  DownloadIcon,
  RepeatIcon,
  XIcon,
} from '@/registry/ndeko/lib/icons';
import { springOf } from '@/registry/ndeko/lib/motion-presets';
import { cn } from '@/registry/ndeko/lib/utils';
import { Badge } from '@/registry/ndeko/ui/badge';
import { Button } from '@/registry/ndeko/ui/button';
import { Fold, Swap } from '@/registry/ndeko/ui/chat-motion';
import { Input } from '@/registry/ndeko/ui/input';
import { ClockGate } from '@/registry/ndeko/ui/live-duration';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';

import { ASK_EXAMPLE } from './ask';
import { csvRowsOf, downloadCsv } from './csv';
import { fieldOf, FIELDS, RECORDS, type FieldId } from './data';
import { CHIP_SHAPE } from './field-chip';
import {
  canAccept,
  pivotOf,
  valueLabelOf,
  WELL_IDS,
  wellOf,
  type PivotTable,
  type WellId,
  type Wells,
} from './pivot';
import { formatValue, PivotTableView } from './pivot-table';
import {
  INITIAL,
  LOOP_AFTER_MS,
  reducer,
  RESTING,
  SCRIPT,
  shownWellsOf,
  type PivotAction,
  type Preview,
} from './session';
import { FieldList, WellGrid } from './wells';

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
};

const MOUSE = { activationConstraint: { distance: 4 } };

const TOUCH = { activationConstraint: { delay: 180, tolerance: 6 } };

const EXPORTED_FOR_MS = 1600;

const FILE_NAME = 'agent-runs-pivot.csv';

function fieldOfDragId(id: unknown): FieldId | null {
  const [, fieldId] = String(id).split(':');
  const field = FIELDS.find((candidate) => candidate.id === fieldId);
  return field?.id ?? null;
}

function wellOfDropId(id: unknown): WellId | null {
  const well = WELL_IDS.find((candidate) => candidate === id);
  return well ?? null;
}

/** The preview a held field gives over a well that can take it. */
function previewFor(
  field: FieldId | null,
  well: WellId | null
): Preview | null {
  if (field === null || well === null) {
    return null;
  }
  if (!canAccept(well, field)) {
    return null;
  }
  return { field, well };
}

/** A preview only lives while something holds the field: the demonstration, or a person's pointer. */
function livePreviewOf(isHeld: boolean, preview: Preview | null) {
  if (isHeld) {
    return preview;
  }
  return null;
}

/** Where every field sits. Chips only measure themselves again when it changes. */
function placementOf(wells: Wells) {
  const places = FIELDS.map((field) => {
    const well = wellOf(wells, field.id) ?? 'list';
    return `${field.id}:${well}`;
  });
  return places.join(' ');
}

function runsWordOf(count: number) {
  if (count === 1) {
    return '1 run';
  }
  return `${count} runs`;
}

function headlineOf(table: PivotTable) {
  const [firstValue] = table.values;
  const [firstTotal] = table.grandTotals;
  if (!firstValue || !firstTotal) {
    return { figure: runsWordOf(table.recordCount), label: 'in last week' };
  }
  return {
    figure: formatValue(firstValue, firstTotal.value),
    label: `${valueLabelOf(firstValue)}, ${runsWordOf(table.recordCount)}`,
  };
}

function lowerLabelOf(id: FieldId) {
  return fieldOf(id).label.toLowerCase();
}

/** Sum of cost by agent and model per day: the table said in one line. */
function titleOf(table: PivotTable, wells: Wells) {
  const valueLabels = table.values.map(valueLabelOf);
  const rows = wells.rows.map(lowerLabelOf);
  const columns = wells.columns.map(lowerLabelOf);
  let title = valueLabels.join(' and ');
  if (rows.length > 0) {
    title = `${title} by ${rows.join(' and ')}`;
  }
  if (columns.length > 0) {
    title = `${title} per ${columns.join(' and ')}`;
  }
  return title;
}

function exportWordOf(isExported: boolean) {
  if (isExported) {
    return 'Downloaded';
  }
  return 'Export CSV';
}

function pressedQuietOf(isPressed: boolean) {
  if (isPressed) {
    return 'scale-[0.94] bg-foreground/[0.07]';
  }
  return undefined;
}

function pressedSolidOf(isPressed: boolean) {
  if (isPressed) {
    return 'scale-[0.94] bg-primary/85';
  }
  return undefined;
}

function spokenUnless(isDemonstrating: boolean, message: string) {
  if (isDemonstrating) {
    return '';
  }
  return message;
}

const ASK_FAILED_LINE =
  'No field in that question. Name a figure and a field, like cost by model per day.';

function spokenLineOf(hasAskFailed: boolean, title: string) {
  if (hasAskFailed) {
    return ASK_FAILED_LINE;
  }
  return `Table: ${title}`;
}

function describedByOf(hasAskFailed: boolean, hintId: string) {
  if (hasAskFailed) {
    return hintId;
  }
  return undefined;
}

export default function AgentOps09() {
  const {
    ref,
    isInView,
    isAutoplaying,
    state,
    act,
    pressed,
    isFinished,
    restart,
  } = useSession(SESSION);
  const { schedule } = useTimeouts();
  const shouldReduceMotion = useReducedMotion();
  const travel = springOf(shouldReduceMotion);
  const groupId = useId();
  const dndId = useId();
  const askId = useId();
  const askHintId = useId();
  const [draggedField, setDraggedField] = useState<FieldId | null>(null);
  const [isExported, setIsExported] = useState(false);
  const sensors = useSensors(
    useSensor(MouseSensor, MOUSE),
    useSensor(TouchSensor, TOUCH)
  );
  const isHeld = isAutoplaying || draggedField !== null;
  const preview = livePreviewOf(isHeld, state.preview);
  const shownWells = shownWellsOf(state.wells, preview);
  const table = pivotOf(RECORDS, shownWells, state.collapsed);
  const placement = placementOf(state.wells);
  const headline = headlineOf(table);
  const title = titleOf(table, shownWells);
  const hasValues = table.values.length > 0;
  const canExport = hasValues && table.recordCount > 0;
  const exportWord = exportWordOf(isExported);
  const spokenLine = spokenLineOf(state.hasAskFailed, title);
  const message = spokenUnless(isAutoplaying, spokenLine);
  const askDescribedBy = describedByOf(state.hasAskFailed, askHintId);
  const canReplay = isFinished && !isAutoplaying;
  let draggedLabel: string | null = null;
  if (draggedField) {
    draggedLabel = fieldOf(draggedField).label;
  }

  function focusLater(selector: string) {
    requestAnimationFrame(() => {
      const target = ref.current?.querySelector<HTMLElement>(selector);
      target?.focus();
    });
  }

  /** A chip that changes place is a new element: the focus follows it to its menu button. */
  function actOnChip(action: PivotAction) {
    act(action);
    const movesChip = action.type === 'placed' || action.type === 'removed';
    if (movesChip) {
      focusLater(`[data-chip-menu="${action.field}"]`);
    }
  }

  function startDrag({ active }: DragStartEvent) {
    setDraggedField(fieldOfDragId(active.id));
  }

  function dragOver({ active, over }: DragOverEvent) {
    const field = fieldOfDragId(active.id);
    const well = wellOfDropId(over?.id);
    act({ type: 'previewed', preview: previewFor(field, well) });
  }

  function endDrag({ active, over }: DragEndEvent) {
    const field = fieldOfDragId(active.id);
    const well = wellOfDropId(over?.id);
    const drop = previewFor(field, well);
    setDraggedField(null);
    if (drop) {
      act({ type: 'placed', field: drop.field, well: drop.well, isDrop: true });
      return;
    }
    act({ type: 'previewed', preview: null });
  }

  function cancelDrag() {
    setDraggedField(null);
    act({ type: 'previewed', preview: null });
  }

  function ask(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    act({ type: 'asked' });
  }

  function exportCsv() {
    downloadCsv(FILE_NAME, csvRowsOf(table));
    setIsExported(true);
    schedule(() => setIsExported(false), EXPORTED_FOR_MS);
  }

  return (
    <ClockGate isActive={isInView}>
      <div
        ref={ref}
        className='bg-background text-foreground @container min-h-dvh w-full'
      >
        <div className='mx-auto flex max-w-6xl flex-col gap-4 p-4 @3xl:gap-5 @3xl:p-8'>
          <header className='flex flex-wrap items-center gap-x-3 gap-y-2'>
            <div className='flex min-w-0 flex-1 flex-col gap-0.5'>
              <h1 className='text-lg font-semibold text-balance'>Run pivot</h1>
              <p className='text-muted-foreground flex flex-wrap items-center gap-x-2 gap-y-1 text-xs'>
                {runsWordOf(RECORDS.length)} last week
                <Badge variant='secondary'>Illustrative</Badge>
              </p>
            </div>
            <ReplayButton
              isShown={canReplay}
              onReplay={restart}
              label='Replay the pivot'
            />
          </header>

          <form onSubmit={ask} className='flex flex-col gap-1.5'>
            <div className='flex items-center gap-2'>
              <label htmlFor={askId} className='sr-only'>
                Ask to pivot
              </label>
              <Input
                id={askId}
                autoComplete='off'
                placeholder={`Ask to pivot: ${ASK_EXAMPLE}`}
                value={state.question}
                aria-invalid={state.hasAskFailed}
                aria-describedby={askDescribedBy}
                onChange={(event) =>
                  act({ type: 'questionTyped', text: event.target.value })
                }
              />
              <Button
                type='submit'
                className={cn('shrink-0', pressedSolidOf(pressed === 'ask'))}
              >
                Ask
              </Button>
            </div>
            <Fold open={state.hasAskFailed}>
              <p id={askHintId} className='text-destructive-ink text-xs'>
                {ASK_FAILED_LINE}
              </p>
            </Fold>
          </form>

          <DndContext
            id={dndId}
            sensors={sensors}
            collisionDetection={pointerWithin}
            onDragStart={startDrag}
            onDragOver={dragOver}
            onDragEnd={endDrag}
            onDragCancel={cancelDrag}
          >
            <LayoutGroup id={groupId}>
              <div className='flex flex-col gap-4 @4xl:flex-row @4xl:items-start @4xl:gap-6'>
                <div className='@4xl:w-44 @4xl:shrink-0'>
                  <FieldList
                    wells={state.wells}
                    placement={placement}
                    travel={travel}
                    drops={state.drops}
                    pressed={pressed}
                    onAction={actOnChip}
                  />
                </div>
                <div className='flex min-w-0 flex-1 flex-col gap-4'>
                  <WellGrid
                    wells={state.wells}
                    preview={preview}
                    draggedField={draggedField}
                    placement={placement}
                    travel={travel}
                    drops={state.drops}
                    pressed={pressed}
                    onAction={actOnChip}
                  />

                  <div className='flex flex-wrap items-end justify-between gap-x-4 gap-y-2'>
                    <div className='flex min-w-0 flex-col'>
                      <p className='text-2xl leading-8 font-semibold tabular-nums'>
                        <Swap swapKey={headline.figure}>{headline.figure}</Swap>
                      </p>
                      <p className='text-muted-foreground text-xs'>
                        <Swap swapKey={headline.label}>{headline.label}</Swap>
                      </p>
                    </div>
                    <div className='flex flex-wrap items-center gap-2'>
                      <Button
                        type='button'
                        variant='outline'
                        size='sm'
                        onClick={() => act({ type: 'swapped' })}
                        className={pressedQuietOf(pressed === 'swap')}
                      >
                        <RepeatIcon />
                        Swap
                      </Button>
                      <Button
                        type='button'
                        variant='outline'
                        size='sm'
                        onClick={() => act({ type: 'cleared' })}
                      >
                        <XIcon />
                        Clear
                      </Button>
                      <Button
                        type='button'
                        variant='outline'
                        size='sm'
                        disabled={!canExport}
                        onClick={exportCsv}
                      >
                        <Swap swapKey={String(isExported)}>
                          {isExported && <CheckIcon />}
                          {!isExported && <DownloadIcon />}
                        </Swap>
                        <Swap swapKey={exportWord}>{exportWord}</Swap>
                      </Button>
                    </div>
                  </div>

                  <PivotTableView
                    table={table}
                    title={title}
                    collapsed={state.collapsed}
                    pressed={pressed}
                    onAction={act}
                  />
                </div>
              </div>
            </LayoutGroup>
            <DragOverlay dropAnimation={null}>
              {draggedLabel && (
                <span
                  className={cn(
                    CHIP_SHAPE,
                    'surface-raised cursor-grabbing pe-2'
                  )}
                >
                  {draggedLabel}
                </span>
              )}
            </DragOverlay>
          </DndContext>
        </div>
        <LiveRegion message={message} />
      </div>
    </ClockGate>
  );
}

'use client';

import { useDroppable } from '@dnd-kit/core';
import type { Transition } from 'motion/react';

import { cn } from '@/registry/ndeko/lib/utils';
import { Swap } from '@/registry/ndeko/ui/chat-motion';

import { fieldOf, FIELDS, type Field, type FieldId } from './data';
import { CHIP_SHAPE, FieldChip } from './field-chip';
import {
  canAccept,
  filterLabelOf,
  valueLabelOf,
  WELL_IDS,
  WELL_LABEL,
  wellOf,
  type WellId,
  type Wells,
} from './pivot';
import type { PivotAction, Preview } from './session';

const WELL_HINT: Record<WellId, string> = {
  filters: 'Keep only some runs',
  columns: 'One field across the top',
  rows: 'Up to two fields down the side',
  values: 'The figures in the cells',
};

const REFUSAL: Record<WellId, string> = {
  filters: 'Takes a field to group by, not a figure',
  columns: 'Takes a field to group by, not a figure',
  rows: 'Takes a field to group by, not a figure',
  values: 'Takes a figure: runs, cost, tokens or duration',
};

type ChipEntry = {
  field: Field;
  label: string;
};

function entriesOf(wells: Wells, well: WellId): ChipEntry[] {
  if (well === 'filters') {
    return wells.filters.map((filter) => ({
      field: fieldOf(filter.field),
      label: filterLabelOf(filter),
    }));
  }
  if (well === 'values') {
    return wells.values.map((value) => ({
      field: fieldOf(value.measure),
      label: valueLabelOf(value),
    }));
  }
  return wells[well].map((dimension) => {
    const field = fieldOf(dimension);
    return { field, label: field.label };
  });
}

type WellTone = 'rest' | 'taking' | 'refusing';

const TONE_CLASS: Record<WellTone, string> = {
  rest: 'bg-foreground/[0.03] ring-transparent dark:bg-foreground/[0.05]',
  taking: 'bg-primary/[0.07] ring-primary/30',
  refusing: 'bg-destructive/[0.06] ring-destructive/25',
};

function toneOf(isTaking: boolean, isRefusing: boolean): WellTone {
  if (isTaking) {
    return 'taking';
  }
  if (isRefusing) {
    return 'refusing';
  }
  return 'rest';
}

function hintOf(well: WellId, isRefusing: boolean) {
  if (isRefusing) {
    return REFUSAL[well];
  }
  return WELL_HINT[well];
}

export type ChipSharedProps = {
  /** The committed wells: chips sit where they were dropped, whatever is being previewed. */
  wells: Wells;
  placement: string;
  travel: Transition;
  drops: Partial<Record<FieldId, number>>;
  pressed: string | null;
  onAction: (action: PivotAction) => void;
};

/** A well refuses the held field when it is a figure over a grouping well, or the reverse. */
function refusesField(
  well: WellId,
  isOver: boolean,
  draggedField: FieldId | null
) {
  if (!isOver || draggedField === null) {
    return false;
  }
  return !canAccept(well, draggedField);
}

/** The field held over this well, unless it already sits there. */
function previewFieldOf(preview: Preview | null, well: WellId, wells: Wells) {
  if (preview?.well !== well) {
    return null;
  }
  const isAlreadyThere = wellOf(wells, preview.field) === well;
  if (isAlreadyThere) {
    return null;
  }
  return fieldOf(preview.field);
}

function layoutIdOf(field: FieldId, drops: Partial<Record<FieldId, number>>) {
  const dropCount = drops[field] ?? 0;
  return `${field}:${dropCount}`;
}

type WellProps = ChipSharedProps & {
  well: WellId;
  preview: Preview | null;
  draggedField: FieldId | null;
};

function Well({
  well,
  preview,
  draggedField,
  wells,
  placement,
  travel,
  drops,
  onAction,
}: WellProps) {
  const { setNodeRef, isOver } = useDroppable({ id: well });
  const entries = entriesOf(wells, well);
  const isTaking = preview?.well === well;
  const isRefusing = refusesField(well, isOver, draggedField);
  const tone = toneOf(isTaking, isRefusing);
  const hint = hintOf(well, isRefusing);
  const previewField = previewFieldOf(preview, well, wells);
  const hasChips = entries.length > 0 || previewField !== null;

  return (
    <div
      ref={setNodeRef}
      className={cn(
        'hairline-ring flex min-h-11 flex-col gap-1.5 rounded-lg p-2 transition-[background-color,box-shadow] duration-150',
        TONE_CLASS[tone]
      )}
    >
      <h3 className='text-muted-foreground flex items-baseline gap-2 text-xs'>
        <span className='text-foreground font-medium'>{WELL_LABEL[well]}</span>
        <span className='min-w-0 truncate'>
          <Swap swapKey={hint}>{hint}</Swap>
        </span>
      </h3>
      {hasChips && (
        <ul className='flex flex-wrap items-center gap-1.5'>
          {entries.map((entry) => (
            <li key={entry.field.id} className='max-w-full'>
              <FieldChip
                field={entry.field}
                origin='well'
                label={entry.label}
                wells={wells}
                layoutId={layoutIdOf(entry.field.id, drops)}
                placement={placement}
                travel={travel}
                onAction={onAction}
              />
            </li>
          ))}
          {previewField && (
            <li
              aria-hidden='true'
              className={cn(
                CHIP_SHAPE,
                'hairline-border border-primary/50 text-primary-ink border-dashed pe-2 transition-opacity duration-150 starting:opacity-0'
              )}
            >
              {previewField.label}
            </li>
          )}
        </ul>
      )}
    </div>
  );
}

type WellGridProps = ChipSharedProps & {
  preview: Preview | null;
  draggedField: FieldId | null;
};

export function WellGrid({ preview, draggedField, ...shared }: WellGridProps) {
  return (
    <section
      aria-label='Layout of the table'
      className='grid grid-cols-1 gap-2 @lg:grid-cols-2'
    >
      {WELL_IDS.map((well) => (
        <Well
          key={well}
          well={well}
          preview={preview}
          draggedField={draggedField}
          {...shared}
        />
      ))}
    </section>
  );
}

export function FieldList({
  wells,
  placement,
  travel,
  drops,
  pressed,
  onAction,
}: ChipSharedProps) {
  return (
    <section aria-label='Fields' className='flex flex-col gap-2'>
      <h2 className='text-muted-foreground text-xs'>Fields</h2>
      <ul className='flex flex-wrap gap-1.5 @4xl:flex-col @4xl:items-start'>
        {FIELDS.map((field) => {
          const well = wellOf(wells, field.id);
          return (
            <li key={field.id} className='flex min-h-7 max-w-full'>
              {well === null && (
                <FieldChip
                  field={field}
                  origin='list'
                  label={field.label}
                  wells={wells}
                  layoutId={layoutIdOf(field.id, drops)}
                  placement={placement}
                  travel={travel}
                  isPressed={pressed === `field-${field.id}`}
                  onAction={onAction}
                />
              )}
              {well !== null && (
                <span
                  className={cn(
                    CHIP_SHAPE,
                    'hairline-border border-foreground/20 text-muted-foreground gap-1.5 border-dashed pe-2 font-normal'
                  )}
                >
                  {field.label}
                  <span className='text-muted-foreground/70'>
                    in {WELL_LABEL[well]}
                  </span>
                </span>
              )}
            </li>
          );
        })}
      </ul>
    </section>
  );
}

'use client';

import { useDraggable } from '@dnd-kit/core';
import { motion, type Transition } from 'motion/react';

import { ChevronDownIcon, HashIcon, XIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/registry/ndeko/ui/dropdown-menu';

import { DIMENSION_VALUES, isMeasure, type Field } from './data';
import {
  AGGREGATION_WORD,
  AGGREGATIONS,
  canAccept,
  WELL_IDS,
  WELL_LABEL,
  wellOf,
  type Wells,
} from './pivot';
import type { PivotAction } from './session';

export type ChipOrigin = 'list' | 'well';

/** Unplaced fields are plain pills; a field placed in a well wears the brand chip of an assigned value. */
const SURFACE: Record<ChipOrigin, string> = {
  list: 'bg-card hairline-ring ring-foreground/12 text-foreground shadow-[0_1px_2px_rgb(0_0_0/0.05)] dark:bg-foreground/[0.04] dark:ring-foreground/15',
  well: 'chip-3d [--chip:var(--primary)]',
};

export const CHIP_SHAPE =
  'inline-flex h-7 max-w-full items-center gap-1 rounded-md ps-2 text-xs font-medium whitespace-nowrap';

const CHIP_BUTTON =
  'focus-visible:ring-ring/25 flex size-6 shrink-0 cursor-pointer items-center justify-center rounded-sm opacity-70 transition-[opacity,background-color] duration-150 outline-none hover:bg-foreground/[0.08] hover:opacity-100 focus-visible:opacity-100 focus-visible:ring-[3px]';

function pressedOf(isPressed: boolean) {
  if (isPressed) {
    return 'scale-[0.94] bg-foreground/[0.07]';
  }
  return undefined;
}

function moveWordOf(isPlaced: boolean) {
  if (isPlaced) {
    return 'Move to';
  }
  return 'Add to';
}

type ChipMenuProps = {
  field: Field;
  wells: Wells;
  onAction: (action: PivotAction) => void;
};

/** The keyboard path of a chip: every well it can go to, then what its own well lets it change. */
function ChipMenu({ field, wells, onAction }: ChipMenuProps) {
  const current = wellOf(wells, field.id);
  const isPlaced = current !== null;
  const moveWord = moveWordOf(isPlaced);
  const targets = WELL_IDS.filter((well) => {
    const isOpen = canAccept(well, field.id);
    const isElsewhere = well !== current;
    return isOpen && isElsewhere;
  });
  const valueSpec = wells.values.find((value) => value.measure === field.id);
  const filter = wells.filters.find((entry) => entry.field === field.id);

  function changeAggregation(next: unknown) {
    const aggregation = AGGREGATIONS.find((candidate) => candidate === next);
    if (aggregation && isMeasure(field.id)) {
      onAction({ type: 'aggregation', measure: field.id, aggregation });
    }
  }

  return (
    <DropdownMenuContent align='start' className='min-w-44'>
      {targets.map((well) => (
        <DropdownMenuItem
          key={well}
          onClick={() => onAction({ type: 'placed', field: field.id, well })}
        >
          {moveWord} {WELL_LABEL[well]}
        </DropdownMenuItem>
      ))}
      {valueSpec && (
        <>
          <DropdownMenuSeparator />
          <DropdownMenuLabel>Summarise by</DropdownMenuLabel>
          <DropdownMenuRadioGroup
            value={valueSpec.aggregation}
            onValueChange={changeAggregation}
          >
            {AGGREGATIONS.map((aggregation) => (
              <DropdownMenuRadioItem key={aggregation} value={aggregation}>
                {AGGREGATION_WORD[aggregation]}
              </DropdownMenuRadioItem>
            ))}
          </DropdownMenuRadioGroup>
        </>
      )}
      {filter && (
        <>
          <DropdownMenuSeparator />
          <DropdownMenuLabel>Keep</DropdownMenuLabel>
          {DIMENSION_VALUES[filter.field].map((value) => (
            <DropdownMenuCheckboxItem
              key={value}
              checked={filter.values.includes(value)}
              onCheckedChange={() =>
                onAction({ type: 'filterValue', field: filter.field, value })
              }
            >
              {value}
            </DropdownMenuCheckboxItem>
          ))}
        </>
      )}
      {current !== null && (
        <>
          <DropdownMenuSeparator />
          <DropdownMenuItem
            onClick={() => onAction({ type: 'removed', field: field.id })}
          >
            Remove from {WELL_LABEL[current]}
          </DropdownMenuItem>
        </>
      )}
    </DropdownMenuContent>
  );
}

export type FieldChipProps = {
  field: Field;
  origin: ChipOrigin;
  /** What the chip says: the field in the list, the field with its setting in a well. */
  label: string;
  wells: Wells;
  layoutId: string;
  /** Where every field sits: the chip measures itself again when it changes. */
  placement: string;
  travel: Transition;
  isPressed?: boolean;
  onAction: (action: PivotAction) => void;
};

export function FieldChip({
  field,
  origin,
  label,
  wells,
  layoutId,
  placement,
  travel,
  isPressed = false,
  onAction,
}: FieldChipProps) {
  const { setNodeRef, listeners, isDragging } = useDraggable({
    id: `${origin}:${field.id}`,
  });
  const isInWell = origin === 'well';
  const isMeasureField = field.kind === 'measure';

  return (
    <motion.div
      layout='position'
      layoutId={layoutId}
      layoutDependency={placement}
      transition={{ layout: travel }}
      className='inline-flex max-w-full'
    >
      <div
        ref={setNodeRef}
        {...listeners}
        className={cn(
          CHIP_SHAPE,
          SURFACE[origin],
          'cursor-grab touch-manipulation transition-[scale,opacity,background-color] duration-150 select-none active:cursor-grabbing',
          isDragging && 'opacity-40',
          pressedOf(isPressed)
        )}
      >
        {isMeasureField && (
          <HashIcon aria-hidden='true' className='size-3 shrink-0 opacity-60' />
        )}
        <span className='min-w-0 truncate'>{label}</span>
        <DropdownMenu>
          <DropdownMenuTrigger
            data-chip-menu={field.id}
            aria-label={`${label}: where it goes`}
            className={CHIP_BUTTON}
          >
            <ChevronDownIcon className='size-3.5' />
          </DropdownMenuTrigger>
          <ChipMenu field={field} wells={wells} onAction={onAction} />
        </DropdownMenu>
        {isInWell && (
          <button
            type='button'
            aria-label={`Remove ${label}`}
            onClick={() => onAction({ type: 'removed', field: field.id })}
            className={cn(CHIP_BUTTON, '-ms-1')}
          >
            <XIcon className='size-3.5' />
          </button>
        )}
        {!isInWell && <span aria-hidden='true' className='w-0.5' />}
      </div>
    </motion.div>
  );
}

