      </div>
    );
  }

  if (!hasRecords) {
    return (
      <div className={cn(SURFACE, 'flex flex-col items-start gap-3 p-4')}>
        <p className='text-muted-foreground text-[13px]'>
          No run matches these filters
        </p>
        <Button
          type='button'
          variant='outline'
          size='sm'
          onClick={() => onAction({ type: 'filtersCleared' })}
