              {table.grandCells.map((cell, index) => (
                <FigureCell
                  key={index}
                  cell={cell}
                  spec={table.values[index % table.values.length]}
                  isStrong
                />
              ))}
              {table.hasColumns &&
                table.grandTotals.map((cell, index) => (
                  <FigureCell
                    key={`total-${index}`}
                    cell={cell}
                    spec={table.values[index]}
                    isStrong
                  />
                ))}
            </tr>
          </tfoot>
        </table>
      </div>
      <HeatLegend />
    </div>
  );
