import {
  DIMENSION_VALUES,
  fieldOf,
  isDimension,
  isMeasure,
  type DimensionId,
  type FieldId,
  type MeasureId,
  type RunRecord,
} from './data';

export type Aggregation = 'sum' | 'avg' | 'count';

export const AGGREGATIONS: Aggregation[] = ['sum', 'avg', 'count'];

export const AGGREGATION_WORD: Record<Aggregation, string> = {
  sum: 'Sum',
  avg: 'Average',
  count: 'Count',
};

export type ValueSpec = {
  measure: MeasureId;
  aggregation: Aggregation;
};

export type FilterSpec = {
  field: DimensionId;
  /** The values that are kept. */
  values: string[];
};

export type Wells = {
  filters: FilterSpec[];
  columns: DimensionId[];
  rows: DimensionId[];
  values: ValueSpec[];
};

export type WellId = 'filters' | 'columns' | 'rows' | 'values';

export const WELL_IDS: WellId[] = ['filters', 'columns', 'rows', 'values'];

export const WELL_LABEL: Record<WellId, string> = {
  filters: 'Filters',
  columns: 'Columns',
  rows: 'Rows',
  values: 'Values',
};

/** How many fields a well holds. One more replaces the last one. */
const CAPACITY: Record<WellId, number> = {
  filters: 3,
  columns: 1,
  rows: 2,
  values: 2,
};

export const EMPTY_WELLS: Wells = {
  filters: [],
  columns: [],
  rows: [],
  values: [],
};

/** Measures are figures and go to Values; everything else groups or filters. */
export function canAccept(well: WellId, field: FieldId) {
  if (well === 'values') {
    return isMeasure(field);
  }
  return isDimension(field);
}

export function wellOf(wells: Wells, field: FieldId): WellId | null {
  if (wells.filters.some((filter) => filter.field === field)) {
    return 'filters';
  }
  if (wells.columns.some((dimension) => dimension === field)) {
    return 'columns';
  }
  if (wells.rows.some((dimension) => dimension === field)) {
    return 'rows';
  }
  if (wells.values.some((value) => value.measure === field)) {
    return 'values';
  }
  return null;
}

export function removed(wells: Wells, field: FieldId): Wells {
  return {
    filters: wells.filters.filter((filter) => filter.field !== field),
    columns: wells.columns.filter((dimension) => dimension !== field),
    rows: wells.rows.filter((dimension) => dimension !== field),
    values: wells.values.filter((value) => value.measure !== field),
  };
}

/** Keeps the first entries and gives the last place to the newcomer. */
function fitted<Entry>(entries: Entry[], entry: Entry, capacity: number) {
  const kept = entries.slice(0, capacity - 1);
  return [...kept, entry];
}

/** Only finished runs by default, the usual first question about a status. */
function defaultFilterOf(field: DimensionId): FilterSpec {
  if (field === 'status') {
    return { field, values: ['Done'] };
  }
  return { field, values: DIMENSION_VALUES[field] };
}

function placedDimension(wells: Wells, field: DimensionId, well: WellId) {
  if (well === 'filters') {
    const filter = defaultFilterOf(field);
    const filters = fitted(wells.filters, filter, CAPACITY.filters);
    return { ...wells, filters };
  }
  if (well === 'columns') {
    const columns = fitted(wells.columns, field, CAPACITY.columns);
    return { ...wells, columns };
  }
  const rows = fitted(wells.rows, field, CAPACITY.rows);
  return { ...wells, rows };
}

/** A field sits in one well at a time: placing it takes it out of the well it was in. */
export function placed(wells: Wells, field: FieldId, well: WellId): Wells {
  if (!canAccept(well, field)) {
    return wells;
  }
  if (wellOf(wells, field) === well) {
    return wells;
  }
  const cleared = removed(wells, field);
  if (isMeasure(field)) {
    const spec: ValueSpec = { measure: field, aggregation: 'sum' };
    const values = fitted(cleared.values, spec, CAPACITY.values);
    return { ...cleared, values };
  }
  if (isDimension(field)) {
    return placedDimension(cleared, field, well);
  }
  return wells;
}

export function swapped(wells: Wells): Wells {
  const columns = wells.rows.slice(0, CAPACITY.columns);
  const rows = wells.columns.slice(0, CAPACITY.rows);
  return { ...wells, columns, rows };
}

export function withAggregation(
  wells: Wells,
  measure: MeasureId,
  aggregation: Aggregation
): Wells {
  const values = wells.values.map((value) => {
    if (value.measure === measure) {
      return { ...value, aggregation };
    }
    return value;
  });
  return { ...wells, values };
}

export function withFilterValue(
  wells: Wells,
  field: DimensionId,
  value: string
): Wells {
  const filters = wells.filters.map((filter) => {
    if (filter.field !== field) {
      return filter;
    }
    const isKept = filter.values.includes(value);
    if (isKept) {
      const values = filter.values.filter((candidate) => candidate !== value);
      return { ...filter, values };
    }
    return { ...filter, values: [...filter.values, value] };
  });
  return { ...wells, filters };
}

export function valueLabelOf(spec: ValueSpec) {
  const measure = fieldOf(spec.measure).label.toLowerCase();
  if (spec.aggregation === 'count') {
    return 'Count of runs';
  }
  return `${AGGREGATION_WORD[spec.aggregation]} of ${measure}`;
}

export function filterLabelOf(filter: FilterSpec) {
  const label = fieldOf(filter.field).label;
  const all = DIMENSION_VALUES[filter.field];
  if (filter.values.length === all.length) {
    return `${label}: all`;
  }
  if (filter.values.length === 0) {
    return `${label}: none`;
  }
  if (filter.values.length === 1) {
    return `${label}: ${filter.values[0]}`;
  }
  return `${label}: ${filter.values.length} of ${all.length}`;
}

function passesFilters(record: RunRecord, filters: FilterSpec[]) {
  return filters.every((filter) =>
    filter.values.includes(record[filter.field])
  );
}

function aggregateOf(records: RunRecord[], spec: ValueSpec) {
  if (records.length === 0) {
    return null;
  }
  if (spec.aggregation === 'count') {
    return records.length;
  }
  let sum = 0;
  for (const record of records) {
    sum += record[spec.measure];
  }
  if (spec.aggregation === 'sum') {
    return sum;
  }
  return sum / records.length;
}

/** The values of a dimension that the records hold, in the order of the dimension. */
function presentValuesOf(records: RunRecord[], dimension: DimensionId) {
  return DIMENSION_VALUES[dimension].filter((value) =>
    records.some((record) => record[dimension] === value)
  );
}

function recordsWith(
  records: RunRecord[],
  dimension: DimensionId | undefined,
  value: string
) {
  if (dimension === undefined) {
    return records;
  }
  return records.filter((record) => record[dimension] === value);
}

export type PivotCell = {
  value: number | null;
  /** From 0 to 3 for the cells that are shaded; none for subtotals and totals. */
  heat: number | null;
};

export type PivotRow = {
  key: string;
  label: string;
  depth: number;
  /** A group row sums its children and can fold them. */
  isGroup: boolean;
  /** One cell per column and value, column by column. */
  cells: PivotCell[];
  /** One total per value, across the columns. */
  totals: PivotCell[];
};

export type PivotTable = {
  rowHeader: string;
  /** False without a column field: the cells then are the totals. */
  hasColumns: boolean;
  columnKeys: string[];
  values: ValueSpec[];
  rows: PivotRow[];
  grandCells: PivotCell[];
  grandTotals: PivotCell[];
  recordCount: number;
};

const ALL_COLUMNS = [''];

const HEAT_STEPS = 4;

function plainCellsOf(
  records: RunRecord[],
  columnDimension: DimensionId | undefined,
  columnKeys: string[],
  values: ValueSpec[]
) {
  const cells: PivotCell[] = [];
  for (const columnKey of columnKeys) {
    const inColumn = recordsWith(records, columnDimension, columnKey);
    for (const spec of values) {
      cells.push({ value: aggregateOf(inColumn, spec), heat: null });
    }
  }
  return cells;
}

function totalsOf(records: RunRecord[], values: ValueSpec[]) {
  return values.map((spec): PivotCell => {
    return { value: aggregateOf(records, spec), heat: null };
  });
}

type Range = { min: number; max: number };

/** The range of each value over the rows that are shaded, so a cost never shades a count. */
function rangesOf(rows: PivotRow[], valueCount: number) {
  const ranges: Range[] = [];
  for (let valueIndex = 0; valueIndex < valueCount; valueIndex += 1) {
    ranges.push({ min: Infinity, max: -Infinity });
  }
  for (const row of rows) {
    if (row.isGroup) {
      continue;
    }
    row.cells.forEach((cell, index) => {
      if (cell.value === null) {
        return;
      }
      const range = ranges[index % valueCount];
      range.min = Math.min(range.min, cell.value);
      range.max = Math.max(range.max, cell.value);
    });
  }
  return ranges;
}

function heatOf(value: number, range: Range) {
  const span = range.max - range.min;
  if (span <= 0) {
    return 0;
  }
  const share = (value - range.min) / span;
  const step = Math.floor(share * HEAT_STEPS);
  return Math.min(HEAT_STEPS - 1, step);
}

function shaded(rows: PivotRow[], valueCount: number) {
  const ranges = rangesOf(rows, valueCount);
  return rows.map((row) => {
    if (row.isGroup) {
      return row;
    }
    const cells = row.cells.map((cell, index): PivotCell => {
      if (cell.value === null) {
        return cell;
      }
      const range = ranges[index % valueCount];
      return { value: cell.value, heat: heatOf(cell.value, range) };
    });
    return { ...row, cells };
  });
}

/** Groups the filtered runs by the rows and the column, with a subtotal per group and a grand total. */
export function pivotOf(
  records: RunRecord[],
  wells: Wells,
  collapsed: string[]
): PivotTable {
  const kept = records.filter((record) => passesFilters(record, wells.filters));
  const [columnDimension] = wells.columns;
  const [groupDimension, leafDimension] = wells.rows;
  const values = wells.values;
  let columnKeys = ALL_COLUMNS;
  if (columnDimension) {
    columnKeys = presentValuesOf(kept, columnDimension);
  }

  function rowOf(
    key: string,
    label: string,
    depth: number,
    isGroup: boolean,
    rowRecords: RunRecord[]
  ): PivotRow {
    return {
      key,
      label,
      depth,
      isGroup,
      cells: plainCellsOf(rowRecords, columnDimension, columnKeys, values),
      totals: totalsOf(rowRecords, values),
    };
  }

  const rows: PivotRow[] = [];
  if (!groupDimension) {
    rows.push(rowOf('all', 'All runs', 0, false, kept));
  }
  if (groupDimension) {
    const hasLeaves = leafDimension !== undefined;
    for (const groupValue of presentValuesOf(kept, groupDimension)) {
      const inGroup = recordsWith(kept, groupDimension, groupValue);
      rows.push(rowOf(groupValue, groupValue, 0, hasLeaves, inGroup));
      const isFolded = collapsed.includes(groupValue);
      if (!hasLeaves || isFolded) {
        continue;
      }
      for (const leafValue of presentValuesOf(inGroup, leafDimension)) {
        const inLeaf = recordsWith(inGroup, leafDimension, leafValue);
        const key = `${groupValue}/${leafValue}`;
        rows.push(rowOf(key, leafValue, 1, false, inLeaf));
      }
    }
  }

  let rowHeader = 'Runs';
  if (groupDimension) {
    rowHeader = fieldOf(groupDimension).label;
  }

  return {
    rowHeader,
    hasColumns: columnDimension !== undefined,
    columnKeys,
    values,
    rows: shaded(rows, Math.max(1, values.length)),
    grandCells: plainCellsOf(kept, columnDimension, columnKeys, values),
    grandTotals: totalsOf(kept, values),
    recordCount: kept.length,
  };
}

import {
  DIMENSION_VALUES,
  DIMENSIONS,
  MEASURES,
  type DimensionId,
  type MeasureId,
} from './data';
import type { Aggregation, FilterSpec, ValueSpec, Wells } from './pivot';

export const ASK_EXAMPLE = 'average tokens by model per day';

const MEASURE_WORDS: Record<MeasureId, string[]> = {
  runs: ['runs', 'run'],
  cost: ['cost', 'costs', 'spend', 'spent'],
  tokens: ['tokens', 'token'],
  duration: ['duration', 'time', 'long'],
};

const DIMENSION_WORDS: Record<DimensionId, string[]> = {
  agent: ['agent', 'agents'],
  model: ['model', 'models'],
  day: ['day', 'days', 'daily', 'date'],
  status: ['status', 'outcome'],
  tool: ['tool', 'tools'],
};

const AVERAGE_WORDS = ['average', 'avg', 'mean'];

const COUNT_WORDS = ['count', 'many', 'number'];

/** After one of these the next dimensions become rows. */
const ROW_WORDS = ['by', 'and'];

/** After one of these the next dimension becomes the column. */
const COLUMN_WORDS = ['per', 'across', 'each', 'over'];

const FAILED_WORDS = ['failed', 'failing', 'failures'];

const DONE_WORDS = ['done', 'finished', 'successful', 'succeeded'];

const MAX_ROWS = 2;

function wordsOf(text: string) {
  const lowered = text.toLowerCase();
  const letters = lowered.replace(/[^a-z0-9\s]/g, ' ');
  const trimmed = letters.trim();
  if (trimmed === '') {
    return [];
  }
  return trimmed.split(/\s+/);
}

function hasAny(words: string[], candidates: string[]) {
  return words.some((word) => candidates.includes(word));
}

function measureOf(word: string) {
  return MEASURES.find((measure) => MEASURE_WORDS[measure].includes(word));
}

function dimensionOf(word: string) {
  return DIMENSIONS.find((dimension) =>
    DIMENSION_WORDS[dimension].includes(word)
  );
}

function aggregationOf(words: string[]): Aggregation {
  if (hasAny(words, AVERAGE_WORDS)) {
    return 'avg';
  }
  if (hasAny(words, COUNT_WORDS)) {
    return 'count';
  }
  return 'sum';
}

/** A day is named in full or by its first letters: monday and mon both mean Mon. */
function matchesWord(word: string, valueWord: string, dimension: DimensionId) {
  if (dimension === 'day') {
    return word.startsWith(valueWord);
  }
  return word === valueWord;
}

function isNamed(words: string[], value: string, dimension: DimensionId) {
  const valueWords = wordsOf(value);
  return valueWords.every((valueWord) =>
    words.some((word) => matchesWord(word, valueWord, dimension))
  );
}

/** "claude sonnet" or "coder" in the question keeps only that value of its dimension. */
function namedFiltersOf(words: string[]) {
  const filters: FilterSpec[] = [];
  for (const dimension of DIMENSIONS) {
    if (dimension === 'status') {
      continue;
    }
    const named = DIMENSION_VALUES[dimension].filter((value) =>
      isNamed(words, value, dimension)
    );
    if (named.length > 0) {
      filters.push({ field: dimension, values: named });
    }
  }
  return filters;
}

function statusFilterOf(words: string[]): FilterSpec | null {
  if (hasAny(words, FAILED_WORDS)) {
    return { field: 'status', values: ['Failed'] };
  }
  if (hasAny(words, DONE_WORDS)) {
    return { field: 'status', values: ['Done'] };
  }
  return null;
}

type Placement = {
  rows: DimensionId[];
  columns: DimensionId[];
};

/** Walks the words: "by" sends the next dimensions to the rows, "per" sends the next one to the column. */
function placementOf(words: string[]) {
  const placement: Placement = { rows: [], columns: [] };
  let target: keyof Placement = 'rows';
  for (const word of words) {
    if (ROW_WORDS.includes(word)) {
      target = 'rows';
      continue;
    }
    if (COLUMN_WORDS.includes(word)) {
      target = 'columns';
      continue;
    }
    const dimension = dimensionOf(word);
    if (!dimension) {
      continue;
    }
    const isRow = placement.rows.includes(dimension);
    const isColumn = placement.columns.includes(dimension);
    if (isRow || isColumn) {
      continue;
    }
    const wantsColumn = target === 'columns' && placement.columns.length === 0;
    if (wantsColumn) {
      placement.columns.push(dimension);
      continue;
    }
    if (placement.rows.length < MAX_ROWS) {
      placement.rows.push(dimension);
    }
  }
  return placement;
}

/**
 * Reads a plain question into the four wells with a handful of word lists: no model is called.
 * It returns nothing when the question names no field.
 */
export function wellsOfQuestion(text: string): Wells | null {
  const words = wordsOf(text);
  const measures = words.map(measureOf);
  const measure = measures.find((found) => found !== undefined);
  const placement = placementOf(words);
  const namedFilters = namedFiltersOf(words);
  const statusFilter = statusFilterOf(words);
  const hasMeasure = measure !== undefined;
  const hasDimension = placement.rows.length + placement.columns.length > 0;
  const hasFilter = namedFilters.length > 0 || statusFilter !== null;
  const namesSomething = hasMeasure || hasDimension || hasFilter;
  if (!namesSomething) {
    return null;
  }
  const value: ValueSpec = {
    measure: measure ?? 'runs',
    aggregation: aggregationOf(words),
  };
  const filters = [...namedFilters];
  if (statusFilter) {
    filters.push(statusFilter);
  }
  const grouped = [...placement.rows, ...placement.columns];
  const freeFilters = filters.filter(
    (filter) => !grouped.includes(filter.field)
  );
  return {
    filters: freeFilters,
    columns: placement.columns,
    rows: placement.rows,
    values: [value],
  };
}

import { valueLabelOf, type PivotCell, type PivotTable } from './pivot';

const FORMULA_PREFIXES = ['=', '+', '-', '@'];

/** Spreadsheet apps run a cell that starts with these characters as a formula. */
function neutralizedCellOf(value: string) {
  const startsLikeFormula = FORMULA_PREFIXES.some((prefix) =>
    value.startsWith(prefix)
  );
  if (startsLikeFormula) {
    return `'${value}`;
  }
  return value;
}

function csvCellOf(value: string) {
  const neutralized = neutralizedCellOf(value);
  const escaped = neutralized.replaceAll('"', '""');
  return `"${escaped}"`;
}

function csvLineOf(row: string[]) {
  const cells = row.map(csvCellOf);
  return cells.join(',');
}

/** Figures leave as plain numbers, three decimals at most, so a spreadsheet can add them up. */
function plainOf(cell: PivotCell) {
  if (cell.value === null) {
    return '';
  }
  const rounded = Number(cell.value.toFixed(3));
  return String(rounded);
}

function headingOf(columnKey: string, valueLabel: string) {
  if (columnKey === '') {
    return valueLabel;
  }
  return `${columnKey} ${valueLabel}`;
}

function headerOf(table: PivotTable) {
  const valueLabels = table.values.map(valueLabelOf);
  const header = [table.rowHeader];
  for (const columnKey of table.columnKeys) {
    for (const valueLabel of valueLabels) {
      header.push(headingOf(columnKey, valueLabel));
    }
  }
  if (table.hasColumns) {
    for (const valueLabel of valueLabels) {
      header.push(headingOf('Total', valueLabel));
    }
  }
  return header;
}

function lineOf(
  table: PivotTable,
  label: string,
  cells: PivotCell[],
  totals: PivotCell[]
) {
  const figures = cells.map(plainOf);
  if (!table.hasColumns) {
    return [label, ...figures];
  }
  const totalFigures = totals.map(plainOf);
  return [label, ...figures, ...totalFigures];
}

/** A sub-row is indented under its group, as it is on screen. */
function labelOf(label: string, depth: number) {
  const indent = '  '.repeat(depth);
  return `${indent}${label}`;
}

/** The table as it is on screen: folded groups stay folded in the file. */
export function csvRowsOf(table: PivotTable) {
  const rows = table.rows.map((row) => {
    const label = labelOf(row.label, row.depth);
    return lineOf(table, label, row.cells, row.totals);
  });
  const total = lineOf(table, 'Total', table.grandCells, table.grandTotals);
  return [headerOf(table), ...rows, total];
}

/** Builds the file in the browser and hands it to the download bar: nothing leaves the page. */
export function downloadCsv(fileName: string, rows: string[][]) {
  const lines = rows.map(csvLineOf);
  const text = lines.join('\n');
  const file = new Blob([text], { type: 'text/csv;charset=utf-8' });
  const url = URL.createObjectURL(file);
  const link = document.createElement('a');
  link.href = url;
  link.download = fileName;
  link.click();
  window.setTimeout(() => URL.revokeObjectURL(url), 0);
}

import type { SessionStep } from '@/registry/ndeko/hooks/use-session';

import { ASK_EXAMPLE, wellsOfQuestion } from './ask';
import type { DimensionId, FieldId, MeasureId } from './data';
import {
  EMPTY_WELLS,
  placed,
  removed,
  swapped,
  withAggregation,
  withFilterValue,
  type Aggregation,
  type WellId,
  type Wells,
} from './pivot';

/** A field held over a well: the table already shows what dropping it there gives. */
export type Preview = {
  field: FieldId;
  well: WellId;
};

export type PivotState = {
  wells: Wells;
  preview: Preview | null;
  /** The groups whose rows are folded. */
  collapsed: string[];
  question: string;
  hasAskFailed: boolean;
  /** Counts the drops of each field: a dropped chip lands where it was let go, it does not fly from the list. */
  drops: Partial<Record<FieldId, number>>;
};

export type PivotAction =
  | { type: 'previewed'; preview: Preview | null }
  | { type: 'placed'; field: FieldId; well: WellId; isDrop?: boolean }
  | { type: 'removed'; field: FieldId }
  | { type: 'aggregation'; measure: MeasureId; aggregation: Aggregation }
  | { type: 'filterValue'; field: DimensionId; value: string }
  | { type: 'swapped' }
  | { type: 'cleared' }
  | { type: 'filtersCleared' }
  | { type: 'groupToggled'; key: string }
  | { type: 'questionTyped'; text: string }
  | { type: 'asked' };

type Step = SessionStep<PivotState, PivotAction>;

const FIRST_WELLS: Wells = {
  filters: [],
  columns: [],
  rows: ['agent'],
  values: [{ measure: 'cost', aggregation: 'sum' }],
};

export const INITIAL: PivotState = {
  wells: FIRST_WELLS,
  preview: null,
  collapsed: [],
  question: '',
  hasAskFailed: false,
  drops: {},
};

/** The wells the table is drawn from: the committed ones, or what the held field would give. */
export function shownWellsOf(wells: Wells, preview: Preview | null) {
  if (!preview) {
    return wells;
  }
  return placed(wells, preview.field, preview.well);
}

/** Folded groups belong to the rows they were folded in. */
function withWells(state: PivotState, wells: Wells): PivotState {
  const rowsBefore = state.wells.rows.join(' ');
  const rowsAfter = wells.rows.join(' ');
  if (rowsBefore === rowsAfter) {
    return { ...state, wells, preview: null };
  }
  return { ...state, wells, preview: null, collapsed: [] };
}

function placedIn(
  state: PivotState,
  field: FieldId,
  well: WellId,
  isDrop: boolean
): PivotState {
  const next = withWells(state, placed(state.wells, field, well));
  if (!isDrop) {
    return next;
  }
  const dropCount = state.drops[field] ?? 0;
  return { ...next, drops: { ...state.drops, [field]: dropCount + 1 } };
}

function groupToggled(state: PivotState, key: string): PivotState {
  const isFolded = state.collapsed.includes(key);
  if (isFolded) {
    const collapsed = state.collapsed.filter((candidate) => candidate !== key);
    return { ...state, collapsed };
  }
  return { ...state, collapsed: [...state.collapsed, key] };
}

function asked(state: PivotState): PivotState {
  const wells = wellsOfQuestion(state.question);
  if (!wells) {
    return { ...state, hasAskFailed: true };
  }
  const next = withWells(state, wells);
  return { ...next, hasAskFailed: false };
}

export function reducer(state: PivotState, action: PivotAction): PivotState {
  switch (action.type) {
    case 'previewed':
      return { ...state, preview: action.preview };
    case 'placed':
      return placedIn(state, action.field, action.well, action.isDrop ?? false);
    case 'removed':
      return withWells(state, removed(state.wells, action.field));
    case 'aggregation':
      return withWells(
        state,
        withAggregation(state.wells, action.measure, action.aggregation)
      );
    case 'filterValue':
      return withWells(
        state,
        withFilterValue(state.wells, action.field, action.value)
      );
    case 'swapped':
      return withWells(state, swapped(state.wells));
    case 'cleared':
      return withWells(state, EMPTY_WELLS);
    case 'filtersCleared':
      return withWells(state, { ...state.wells, filters: [] });
    case 'groupToggled':
      return groupToggled(state, action.key);
    case 'questionTyped':
      return { ...state, question: action.text, hasAskFailed: false };
    case 'asked':
      return asked(state);
  }
}

const CHUNK = 3;

function delayOfChunk(index: number) {
  if (index === 0) {
    return 1700;
  }
  return 70;
}

function typingSteps(): Step[] {
  const steps: Step[] = [];
  const last = ASK_EXAMPLE.length + CHUNK;
  for (let end = CHUNK; end < last; end += CHUNK) {
    const text = ASK_EXAMPLE.slice(0, end);
    const after = delayOfChunk(steps.length);
    steps.push({
      after,
      by: 'demo',
      action: { type: 'questionTyped', text },
    });
  }
  return steps;
}

/** How long the demonstration holds a field over a well before it lets go. */
const HOLD_MS = 1000;

/** Holds a field over a well, where the table already regroups, then drops it there. */
function dragSteps(after: number, field: FieldId, well: WellId): Step[] {
  return [
    {
      after,
      by: 'demo',
      press: `field-${field}`,
      action: { type: 'previewed', preview: { field, well } },
    },
    { after: HOLD_MS, by: 'demo', action: { type: 'placed', field, well } },
  ];
}

const BUILDING: Step[] = [
  ...dragSteps(1400, 'day', 'columns'),
  ...dragSteps(1500, 'model', 'rows'),
];

export const SCRIPT: Step[] = [
  ...BUILDING,
  {
    after: 1700,
    by: 'demo',
    press: 'group-Coder',
    action: { type: 'groupToggled', key: 'Coder' },
  },
  ...typingSteps(),
  { after: 500, by: 'demo', press: 'ask', action: { type: 'asked' } },
  { after: 2400, by: 'demo', press: 'swap', action: { type: 'swapped' } },
];

/** Under reduced motion the table rests on cost by agent and model per day, groups open. */
function restingOf() {
  let state = INITIAL;
  for (const step of BUILDING) {
    state = reducer(state, step.action);
  }
  return state;
}

export const RESTING = restingOf();

export const LOOP_AFTER_MS = 3800;

import type { BrandSlug } from '@/registry/ndeko/lib/brand-logos';

export type DimensionId = 'agent' | 'model' | 'day' | 'status' | 'tool';

export type MeasureId = 'runs' | 'cost' | 'tokens' | 'duration';

export type FieldId = DimensionId | MeasureId;

export type RunRecord = Record<DimensionId, string> & Record<MeasureId, number>;

export type Field = {
  id: FieldId;
  label: string;
  kind: 'dimension' | 'measure';
};

export const DIMENSIONS: DimensionId[] = [
  'agent',
  'model',
  'day',
  'status',
  'tool',
];

export const MEASURES: MeasureId[] = ['runs', 'cost', 'tokens', 'duration'];

export const FIELDS: Field[] = [
  { id: 'agent', label: 'Agent', kind: 'dimension' },
  { id: 'model', label: 'Model', kind: 'dimension' },
  { id: 'day', label: 'Day', kind: 'dimension' },
  { id: 'status', label: 'Status', kind: 'dimension' },
  { id: 'tool', label: 'Tool', kind: 'dimension' },
  { id: 'runs', label: 'Runs', kind: 'measure' },
  { id: 'cost', label: 'Cost', kind: 'measure' },
  { id: 'tokens', label: 'Tokens', kind: 'measure' },
  { id: 'duration', label: 'Duration', kind: 'measure' },
];

export function fieldOf(id: FieldId) {
  const field = FIELDS.find((candidate) => candidate.id === id);
  return field ?? FIELDS[0];
}

export function isDimension(id: FieldId): id is DimensionId {
  return fieldOf(id).kind === 'dimension';
}

export function isMeasure(id: FieldId): id is MeasureId {
  return fieldOf(id).kind === 'measure';
}

